import fs from 'fs/promises';
import path from 'path';
import crypto from 'crypto';
import { config } from '../config';

/**
 * File storage behind an interface, so "local disk in development, S3-compatible object storage in production" is a
 * configuration change and not a rewrite. Keys are generated by the application (never taken from user input);
 * the local adapter still refuses any key that could escape its root.
 */
export interface Storage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer>;
  delete(key: string): Promise<void>;
}

export class LocalDiskStorage implements Storage {
  private root: string;
  constructor(root: string) {
    this.root = path.resolve(root);
  }
  private resolve(key: string): string {
    if (!/^[A-Za-z0-9/_.-]{1,200}$/.test(key) || key.includes('..') || key.startsWith('/')) throw new Error('Invalid storage key');
    const full = path.resolve(this.root, key);
    if (full !== this.root && !full.startsWith(this.root + path.sep)) throw new Error('Invalid storage key');
    return full;
  }
  /** Write to a temp file and rename: readers never observe a half-written upload, a crash never leaves a truncated file under the real key. */
  async put(key: string, data: Buffer): Promise<void> {
    const full = this.resolve(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    const tmp = `${full}.${crypto.randomBytes(4).toString('hex')}.tmp`;
    await fs.writeFile(tmp, data, { flag: 'wx', mode: 0o640 });
    await fs.rename(tmp, full);
  }
  async get(key: string): Promise<Buffer> {
    return fs.readFile(this.resolve(key));
  }
  async delete(key: string): Promise<void> {
    await fs.rm(this.resolve(key), { force: true });
  }
}

let current: Storage | undefined;
export function getStorage(): Storage {
  return (current ??= new LocalDiskStorage(config.STORAGE_DIR));
}
/** Tests and alternative adapters. */
export function setStorage(s: Storage | undefined) {
  current = s;
}

// ── content sniffing: trust the bytes, not the Content-Type header or the file name ────────────────────────────────────

export type SniffedType = { mime: 'image/jpeg' | 'image/png' | 'image/webp' | 'application/pdf'; kind: 'image' | 'document'; ext: string };

export function sniff(buf: Buffer): SniffedType | null {
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return { mime: 'image/jpeg', kind: 'image', ext: 'jpg' };
  if (buf.length >= 8 && buf.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return { mime: 'image/png', kind: 'image', ext: 'png' };
  if (buf.length >= 12 && buf.subarray(0, 4).toString('latin1') === 'RIFF' && buf.subarray(8, 12).toString('latin1') === 'WEBP') return { mime: 'image/webp', kind: 'image', ext: 'webp' };
  if (buf.length >= 5 && buf.subarray(0, 5).toString('latin1') === '%PDF-') return { mime: 'application/pdf', kind: 'document', ext: 'pdf' };
  return null;
}

/** Display name only (never used as a path): strip directories, control characters and quotes. */
export function safeFileName(raw: string | undefined, fallback: string): string {
  const base = (raw ?? '').split(/[\\/]/).pop() ?? '';
  // eslint-disable-next-line no-control-regex -- removing control characters is the whole point
  const cleaned = base.replace(/[\u0000-\u001f\u007f"<>|?*:]/g, '').trim().slice(0, 150);
  return cleaned || fallback;
}

/**
 * Antivirus hook. The default scanner accepts everything; a deployment that needs it plugs in ClamAV (or a cloud scanner)
 * here and uploads are refused when it flags the bytes.
 */
export interface Scanner {
  scan(data: Buffer): Promise<{ clean: boolean; reason?: string }>;
}
let scanner: Scanner = { scan: async () => ({ clean: true }) };
export const getScanner = () => scanner;
export const setScanner = (s: Scanner) => {
  scanner = s;
};
